package com.optarena.registration;

import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/register")
public class RegistrationController {

    private ResponseEntity<Map<String, String>> validate(String username, String password) {
        if (username == null || username.isBlank()) {
            return ResponseEntity.badRequest().body(Map.of("error", "username must not be blank"));
        }
        if (password == null || password.length() < 8) {
            return ResponseEntity.badRequest().body(Map.of("error", "password must be at least 8 characters"));
        }
        return null;
    }

    @PostMapping
    public ResponseEntity<Map<String, String>> registerUser(@RequestBody Map<String, String> body) {
        String username = body.get("username");
        ResponseEntity<Map<String, String>> error = validate(username, body.get("password"));
        if (error != null) {
            return error;
        }
        return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("username", username, "role", "USER"));
    }

    @PostMapping("/admin")
    public ResponseEntity<Map<String, String>> registerAdmin(@RequestBody Map<String, String> body) {
        String username = body.get("username");
        ResponseEntity<Map<String, String>> error = validate(username, body.get("password"));
        if (error != null) {
            return error;
        }
        return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("username", username, "role", "ADMIN"));
    }
}
